<script>
import {config,auth,request,notify} from '../state.js';import {plain,copy,download,csv,sessionGet,sessionSet} from '../lib.js';import Icon from '../components/Icon.svelte';
// Query text is kept in memory across navigation. Persisting it is opt-in.
let remember=sessionGet('query.remember',false),sql=remember?sessionGet('query.draft','SELECT * FROM system.cluster_status;'):'SELECT * FROM system.cluster_status;',result=null,busy=false,error='',controller,template='';
$: sessionSet('query.remember',remember);$: if(remember)sessionSet('query.draft',sql);else sessionSet('query.draft',null);
const examples=[['cluster','クラスタ状態','SELECT * FROM system.cluster_status;'],['raft','Raftメンバー','SELECT * FROM system.raft_state;'],['keyspaces','Keyspaces','SELECT * FROM system_schema.keyspaces;'],['tables','Tables','SELECT * FROM system_schema.tables;']];
async function run(){if(busy)return;busy=true;error='';controller=new AbortController();try{result=await request('query',{method:'POST',body:JSON.stringify({cql:sql}),signal:controller.signal});}catch(e){error=e.name==='AbortError'?'クエリをキャンセルしました':e.message;}finally{busy=false;controller=null;}}
function example(){const v=examples.find(e=>e[0]===template);if(v)sql=v[2];template='';}
</script>
{#if !$config?.console_enabled}<div class="notice"><Icon name="shield" size={18}/><div><strong>CQLコンソールは無効です</strong><p>有効化する場合は、DBの読み取り専用ユーザーを設定し、Scope設定に <code>console.enabled: true</code> を追加してください。編集欄で下書きはできます。</p></div></div>{/if}
<section class="panel"><header class="panel-header"><h2><Icon name="query" size={17}/> Read-only CQL</h2><select bind:value={template} onchange={example} aria-label="CQLの例"><option value="">クエリ例を選択</option>{#each examples as [id,label]}<option value={id}>{label}</option>{/each}</select></header><div class="query-editor"><textarea aria-label="CQLエディタ" bind:value={sql} spellcheck="false" onkeydown={e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&$config?.console_enabled&&$auth?.authenticated){e.preventDefault();run();}}}></textarea></div><div class="toolbar"><button class="primary" disabled={busy||!$config?.console_enabled||!$auth?.authenticated} onclick={run}><Icon name="play" size={14}/>{busy?'実行中…':'クエリを実行'}</button>{#if busy}<button onclick={()=>controller?.abort()}>キャンセル</button>{/if}<span class="hint">Ctrl / ⌘ + Enter · SELECTのみ · 最大{$config?.max_rows||200}行</span><label class="check-field"><input type="checkbox" bind:checked={remember}/>このタブで下書きを保存</label></div></section>
{#if error}<pre class="notice error-text" role="alert">{error}</pre>{/if}
{#if result}<section class="panel"><header class="panel-header"><h2>結果 <span class="muted-badge">{result.count} rows · {result.took_ms} ms</span></h2><div class="button-group"><button onclick={()=>download('scyllascope-query.csv',csv(result.rows,result.columns),'text/csv;charset=utf-8')}><Icon name="download" size={14}/>CSV</button><button onclick={()=>download('scyllascope-query.json',JSON.stringify(result,null,2))}>JSON</button></div></header>{#if result.truncated}<p class="notice warning">表示上限で切り詰めています。条件を絞って再実行してください。</p>{/if}<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable results must be keyboard reachable.) -->
<div class="table-scroll query-results" tabindex="0" role="region" aria-label="CQL実行結果"><table><thead><tr>{#each result.columns as col}<th>{col}</th>{/each}</tr></thead><tbody>{#each result.rows as row,i (i)}<tr>{#each result.columns as col}<td><span class="cell-value" title={plain(row[col])}>{plain(row[col])}</span></td>{/each}</tr>{/each}</tbody></table></div></section>{:else}<div class="empty compact-empty"><Icon name="query" size={28}/><p>実行結果はここに表示されます。監視の自動更新で入力欄や結果を作り直しません。</p></div>{/if}
